WHO = {'column': [('renmahlsof', 200641), ('psiloldmicr', 200705), ('kisen', 0), ('zecyfeeben', 200769), ('bridgepy', 200769), ('kisen', 200897), ('renmahepy', 0), ('bridsof', 0)], 'bridge': [('mueflldmicr', 200769), ('psiloldmicr', 203126), ('mueflldmicr', 203319), ('mueflldmicr', 204337), ('mueflldmicr', 205738), ('mueflldmicr', 0), ('alphafoldmicro', 211921), ('psiloldmicr', 211921)], 'tree': [('mueflfhlsof', 200958), ('aprillfhlsof', 0), ('renmafocren', 201406), ('zeeceewei', 0), ('renmahepy', 0), ('visha', 201916), ('aprillfhlsof', 0), ('mueflfocren', 0)], 'temple': [('aprillchisha', 201342), ('einlhepy', 0), ('bridgepy', 204974), ('mueflfhlsof', 0), ('renmahepy', 205230), ('mulceffocren', 0), ('aprillchisha', 0), ('aprillchisha', 214977)], 'tower': [('bridfocren', 202874), ('einlhepy', 204721), ('psiloeyeben', 208098), ('bridfocren', 0), ('einlhepy', 0)], 'manor': [('bridsof', 203062), ('mueflfocren', 0), ('mueysen', 204465), ('weiweitem', 205674), ('maefhlsof', 206884), ('aprillchisha', 0), ('aprillfhlsof', 0), ('zeeceewei', 207396)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW316(OracleReleaseRuntimeW315):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
